SELECT id AS "id", code AS "code", name AS "name", next_maintain_date AS "nextDate"
FROM mes_equipment
WHERE status <> 'SCRAPPED' AND next_maintain_date IS NOT NULL AND next_maintain_date <= #{before}

SELECT id AS "id", wo_no AS "woNo", plan_end AS "planEnd", create_by AS "createBy"
FROM mes_work_order
WHERE status IN ('RELEASED', 'STARTED') AND plan_end < #{today}
